<script setup lang="ts">import{ref}from'vue';import AccountShell from'../components/AccountShell.vue';import{cards}from'../data';import{useAppStore}from'../stores/app';const store=useAppStore(),mode=ref<'normal'|'recycle'|'shipping'>('normal'),selected=ref<number[]>([]);function toggle(i:number){selected.value=selected.value.includes(i)?selected.value.filter(x=>x!==i):[...selected.value,i]}</script>
<template><AccountShell><div class="account-title"><div><span class="eyebrow">MY COLLECTION</span><h1>个人主页</h1><p>管理你的 OK Coin 与卡牌收藏。</p></div><button class="btn btn-outline">导出资产记录</button></div><div class="summary"><article class="card balance-card"><span>OK Coin 余额</span><strong>{{store.balance.toLocaleString()}}</strong><small>所有充值、赠送与回收 Coin 均进入统一余额</small><div><RouterLink to="/recharge" class="btn btn-primary">充值 Coin</RouterLink><RouterLink to="/account/transactions" class="btn btn-outline">收支明细</RouterLink></div></article><article class="card warehouse-card"><span>保管中的卡牌</span><strong>4</strong><small>发货门槛为所选卡牌合计 2,000 Coin</small><button class="btn btn-dark" @click="mode='shipping'">申请实物发货</button></article></div><section class="warehouse card"><div class="warehouse-head"><div><h2>卡牌仓库</h2><p>{{mode==='normal'?'查看并管理已获得的卡牌':mode==='recycle'?'请选择要回收的卡牌':'请选择要申请发货的卡牌'}}</p></div><div><button class="btn btn-outline" @click="mode='recycle';selected=[]">批量回收</button><button class="btn btn-dark" @click="mode='shipping';selected=[]">申请发货</button></div></div><div class="warehouse-tools"><div><button class="pill gold">全部</button><button class="pill">保管中</button><button class="pill">发货锁定</button></div><input class="input" placeholder="搜索卡牌名称…"></div><div class="card-grid"><article v-for="(c,i) in cards" class="collect-card" :class="{selected:selected.includes(i)}" @click="mode!=='normal'&&toggle(i)"><div><img :src="c.image" :alt="c.name"><input v-if="mode!=='normal'" type="checkbox" :checked="selected.includes(i)" :disabled="c.status==='发货锁定'"></div><h3>{{c.name}}</h3><p><span class="pill">{{c.tag}}</span><span :class="['pill',c.status==='保管中'?'green':'']">{{c.status}}</span></p><b>可回收 {{c.coin}} Coin</b></article><button class="add-card"><span>＋</span>开启新盲盒</button></div></section><div v-if="mode!=='normal'" class="selection-bar"><div><b>已选择 {{selected.length}} 张</b><span>{{mode==='recycle'?`预计获得 ${selected.reduce((s,i)=>s+cards[i].coin,0)} Coin`:`卡牌合计 ${selected.reduce((s,i)=>s+cards[i].coin,0)} Coin`}}</span></div><button class="btn btn-outline" @click="mode='normal';selected=[]">取消</button><button class="btn btn-primary" :disabled="!selected.length||(mode==='shipping'&&selected.reduce((s,i)=>s+cards[i].coin,0)<2000)" @click="store.toast(mode==='recycle'?'请再次确认回收，完成后不可撤销':'已进入发货申请流程')">{{mode==='recycle'?'确认回收':'下一步'}}</button></div></AccountShell></template>
<style scoped>.account-title{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.account-title h1{margin:4px 0}.account-title p{margin:0;color:var(--muted)}.summary{display:grid;grid-template-columns:2fr 1fr;gap:18px}.summary article{padding:25px}.summary span,.summary small{display:block;color:var(--muted)}.summary strong{display:block;font-size:38px;color:var(--brown);margin:8px 0}.summary small{font-size:11px}.summary article>div{display:flex;gap:10px;margin-top:20px}.warehouse-card{background:var(--brown);color:#fff}.warehouse-card strong,.warehouse-card span,.warehouse-card small{color:inherit}.warehouse-card .btn{margin-top:20px;width:100%;background:white;color:var(--brown)}.warehouse{margin-top:18px;padding:24px}.warehouse-head,.warehouse-tools{display:flex;justify-content:space-between;align-items:center}.warehouse-head h2{margin:0}.warehouse-head p{font-size:12px;color:var(--muted)}.warehouse-head>div:last-child{display:flex;gap:8px}.warehouse-tools{border-top:1px solid var(--line);margin-top:18px;padding-top:18px}.warehouse-tools>div{display:flex;gap:7px}.warehouse-tools .input{width:250px}.card-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:20px}.collect-card{border:2px solid transparent;border-radius:12px;background:#fafaf7;padding:10px}.collect-card.selected{border-color:var(--gold);background:#fffbea}.collect-card>div{aspect-ratio:3/4;position:relative}.collect-card img{width:100%;height:100%;object-fit:cover;border-radius:8px}.collect-card input{position:absolute;right:8px;top:8px;width:20px;height:20px;accent-color:var(--gold)}.collect-card h3{font-size:13px}.collect-card p{display:flex;gap:4px}.collect-card b{font-size:11px;color:var(--brown)}.add-card{border:1px dashed #c9c7bb;border-radius:12px;background:white;display:grid;place-items:center;align-content:center;gap:10px}.add-card span{font-size:34px;color:var(--brown)}.selection-bar{position:fixed;z-index:45;bottom:18px;left:50%;transform:translateX(-50%);width:min(760px,calc(100% - 30px));background:#292819;color:#fff;border-radius:15px;padding:12px 16px;display:flex;align-items:center;gap:12px;box-shadow:0 20px 50px rgba(0,0,0,.25)}.selection-bar>div{margin-right:auto;display:grid}.selection-bar span{font-size:11px;color:#ddd}@media(max-width:900px){.card-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.account-title{display:block}.account-title>.btn{margin-top:15px}.summary{grid-template-columns:1fr}.warehouse{padding:16px}.warehouse-head,.warehouse-tools{align-items:stretch;display:grid;gap:12px}.warehouse-head>div:last-child{display:grid;grid-template-columns:1fr 1fr}.warehouse-tools .input{width:100%}.selection-bar{bottom:8px}.selection-bar .btn{padding:8px;font-size:12px}}</style>
